#!/usr/bin/env bash
# Rebuild upstream/xnu/bsd/hfs from the upstream/hfs submodule.
#
# The HFS+ filesystem normally ships as com.apple.filesystems.hfs.kext with its
# own Xcode project and IOKit personality (hfs_iokit.cpp).  crossxnu builds the
# same core sources straight into the kernel and registers them from
# hfs_kernel_init.c, so the vendor tree is "hfs core sources + crossxnu glue".
#
# upstream/xnu/bsd/hfs is *not* tracked anywhere: it is generated by this
# script, which keeps the repository free of copied Apple source and makes the
# exact set of files reproducible from the submodule pins in .gitmodules.
#
# Usage: scripts/sync-hfs.sh
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=env.sh
source "${SCRIPT_DIR}/env.sh"

HFS="${CROSSXNU_ROOT}/upstream/hfs"
DEST="${CROSSXNU_XNU}/bsd/hfs"
PATCHES="${CROSSXNU_ROOT}/patches/hfs"

if [[ ! -d "${HFS}/core" ]]; then
    echo "error: ${HFS} is not checked out; run 'git submodule update --init upstream/hfs'" >&2
    exit 1
fi
if [[ ! -d "${CROSSXNU_XNU}/.git" && ! -f "${CROSSXNU_XNU}/.git" ]]; then
    echo "error: ${CROSSXNU_XNU} is not a git checkout" >&2
    exit 1
fi

echo "syncing ${HFS}/core -> ${DEST}"
rm -rf "${DEST}"
mkdir -p "${DEST}"

# Core sources, minus the Xcode/kext packaging that the in-kernel build does
# not use (the kext registers through IOKit, we register through VFS).
(cd "${HFS}/core" && find . -type f \
    ! -name '*.plist' \
    ! -name '*.xcconfig' \
    ! -name 'install' \
    ! -name 'mk-root.sh' \
    ! -name 'hfs_iokit.cpp' \
    -print0 | while IFS= read -r -d '' f; do
        install -D -m 644 "$f" "${DEST}/${f#./}"
    done)

# Sources the kext shares with the userland tools.
install -D -m 644 "${HFS}/hfs_encodings/hfs_encodinghint.c" \
    "${DEST}/hfs_encodinghint.c"

# The in-kernel build keeps the encodings sources next to bsd/hfs, because
# bsd/hfs/hfs.h includes "../hfs_encodings/hfs_encodings.h".
rm -rf "${CROSSXNU_XNU}/bsd/hfs_encodings"
mkdir -p "${CROSSXNU_XNU}/bsd/hfs_encodings"
cp -R "${HFS}/hfs_encodings/." "${CROSSXNU_XNU}/bsd/hfs_encodings/"

# crossxnu glue (in-tree, MIT).
cp -R "${PATCHES}/extra/." "${DEST}/"

# Private headers that are declared by crossxnu shims instead of the SDK.
mkdir -p "${DEST}/AppleKeyStore"
install -D -m 644 \
    "${CROSSXNU_ROOT}/toolchain/shims/permissive/AppleKeyStore/AppleKeyStoreFSServices.h" \
    "${DEST}/AppleKeyStore/AppleKeyStoreFSServices.h"

# Adapt the core sources to the in-kernel build (fortify checks, headers).
git -C "${CROSSXNU_XNU}" apply --verbose "${PATCHES}/0001-build-against-xnu.patch"

echo "hfs vendor tree ready: ${DEST}"
